  28 |   useEffect(() => {
  29 |     const controller = new AbortController();
> 30 |     void refresh(controller.signal).catch(failure => {
     |          ^^^^^^^ Avoid calling setState() directly within an effect
  31 |       if (!controller.signal.aborted) setError(failure instanceof Error ? failure.message : 'تعذّر تحميل حالة الموظفين.');
  32 |     });
  33 |     return () => controller.abort();

